insert into public.questions(course_id,position,question,option_a,option_b,option_c,correct_option) select c.id,v.p,v.q,v.a,v.b,v.c,v.k from public.courses c,(values
(1,'Which statement best describes marketing?','Producing goods without customer research','Creating and delivering value to customers','Advertising products only','B'),
(2,'Which example best represents a basic need?','A preference for a particular soft drink brand','A wish for a luxury watch','Hunger requiring food','C'),
(3,'When does a want become demand in marketing?','When backed by willingness and ability to buy','When a seller prints an advertisement','When a product has attractive packaging','A'),
(4,'Which orientation starts with target customers’ needs?','Production orientation','Marketing orientation','Selling orientation','B'),
(5,'Customer value compares perceived benefits with what?','Only the seller’s wage bill','Only competitors’ sales','The customer’s monetary and non-monetary costs','C'),
(6,'Which factor belongs to a firm’s microenvironment?','Its suppliers','National inflation','Population ageing','A'),
(7,'Which is a macroenvironmental influence on marketing?','A particular distributor’s stock level','A nationwide change in consumer protection law','A salesperson’s daily call list','B'),
(8,'Which activity collects primary data?','Reading a published census report','Reviewing an existing industry report','Interviewing customers for a new study','C'),
(9,'What should usually come first in a marketing research project?','Defining the research problem and objectives','Printing the final report','Choosing conclusions before gathering data','A'),
(10,'Which survey practice is most ethical?','Concealing how personal responses will be used','Explaining the study and obtaining informed consent','Publishing identifiable responses without permission','B'),
(11,'What normally starts the consumer buying decision process?','Post-purchase evaluation','Purchase decision','Recognition of a need or problem','C'),
(12,'A student’s purchase influenced by friends illustrates which factor?','Social influence','Climate influence','Production capacity','A'),
(13,'Dividing buyers into age groups is which type of segmentation?','Geographic','Demographic','Behavioural','B'),
(14,'Grouping consumers by lifestyle mainly uses which segmentation basis?','Psychographic','Geographic','Demographic','A'),
(15,'What is targeting?','Designing a company logo','Dividing factory tasks','Selecting market segments to serve','C'),
(16,'Positioning is chiefly concerned with what?','The physical location of every warehouse','How target customers perceive an offering relative to alternatives','The arrangement of machines in a factory','B'),
(17,'Which set contains the traditional four Ps?','People, process, profit and planning','Product, profit, personnel and publicity','Product, price, place and promotion','C'),
(18,'What is a core function of a brand?','Identifying and differentiating an offering','Guaranteeing the lowest price','Eliminating every competitor','A'),
(19,'Which is a useful packaging function?','Replacing the need for a product','Protecting the product during handling','Guaranteeing unlimited shelf life','B'),
(20,'Which product life-cycle stage typically has rapid sales growth after successful introduction?','Decline','Maturity','Growth','C'),
(21,'A product costs ₦2,000 and receives a 25% markup on cost. What is its selling price?','₦2,500','₦2,025','₦2,250','A'),
(22,'Which pricing approach begins with customers’ perceived worth of the offering?','Cost-plus pricing','Value-based pricing','Pricing solely from factory overhead','B'),
(23,'Which channel is direct?','Producer → wholesaler → retailer → consumer','Producer → agent → retailer → consumer','Producer → consumer','C'),
(24,'A retailer mainly sells to which group?','Final consumers for personal use','Manufacturers only for processing','Wholesalers only for resale','A'),
(25,'Making a convenience product available in as many suitable outlets as possible is what?','Exclusive distribution','Intensive distribution','Selective distribution','B'),
(26,'Which activity is sales promotion?','A long-term corporate reputation policy','A routine product delivery','A limited-time discount coupon','C'),
(27,'Which example illustrates personal selling?','A salesperson discussing a buyer’s needs face to face','An unpaid newspaper report','A roadside billboard','A'),
(28,'What is the goal of integrated marketing communications?','Using conflicting claims across channels','Delivering a coordinated, consistent message across channels','Replacing all customer contact with advertising','B'),
(29,'Which set extends the four Ps for service marketing?','Profit, purchasing and production','Packaging, publicity and patents','People, process and physical evidence','C'),
(30,'An advert makes an unsupported claim that a supplement cures every illness. What is the main concern?','Misleading promotion','Intensive distribution','Demographic segmentation','A')
insert into public.questions(course_id,position,question,option_a,option_b,option_c,correct_option) select c.id,v.p,v.q,v.a,v.b,v.c,v.k from public.courses c,(values
(1,'What does the sociology of work primarily examine?','Only the chemical composition of factory inputs','Social relationships and institutions surrounding work','Only the arithmetic of company accounts','B'),
(2,'Which activity is work even though it is not paid employment?','Providing unpaid care for a dependent relative','Receiving a birthday gift','Watching a film solely for leisure','A'),
(3,'What is an occupation?','A single payment received by a business','Every informal friendship at work','A category of work involving a recognised set of activities','C'),
(4,'Which change is closely associated with industrialisation?','Complete disappearance of occupational specialisation','Expansion of mechanised factory production','Universal replacement of cities by farming villages','B'),
(5,'What is the division of labour?','Equal sharing of every worker’s income','A ban on occupational specialisation','Allocation of different tasks among workers','C'),
(6,'In Marx’s analysis, the capitalist class primarily owns what?','The means of production','Only its own capacity to work','All unpaid household labour','A'),
(7,'Which situation best illustrates alienation in Marx’s sense?','Workers lack control over the products and process of their labour','Workers jointly determine every aspect of production','Workers own and freely direct their cooperative enterprise','A'),
(8,'Durkheim associated organic solidarity mainly with what?','Similarity of roles in a minimally differentiated society','The complete absence of social cooperation','Interdependence arising from specialised roles','C'),
(9,'Which feature is central to Weber’s ideal-type bureaucracy?','Appointments based only on family relationships','A hierarchy of offices governed by formal rules','Complete absence of written procedures','B'),
(10,'What is rationalisation in Weber’s analysis?','Growing reliance on calculation, rules and efficiency','Replacing every rule with personal favour','Rejecting all systematic organisation','A'),
(11,'Which is part of a formal organisation?','An unofficial lunchtime friendship','An unapproved peer support network','An officially defined reporting relationship','C'),
(12,'Which example illustrates informal organisation?','The published departmental hierarchy','Workers forming an unofficial mutual-support network','A written schedule of official job duties','B'),
(13,'Scientific management is most closely associated with whom?','Karl Marx','Frederick W. Taylor','Émile Durkheim','B'),
(14,'What is a central aim of scientific management?','Eliminating every form of task measurement','Placing all production decisions with customers','Improving task efficiency through systematic work study','C'),
(15,'What does the human relations approach emphasise?','Social needs and group relationships at work','The irrelevance of worker attitudes','Only the physical design of machinery','A'),
(16,'What are work-group norms?','Only laws enacted by the National Assembly','The total monetary value of company assets','Shared expectations about acceptable behaviour','C'),
(17,'What is organisational culture?','Shared values, assumptions and practices in an organisation','The number of machines in a factory','An organisation’s cash balance alone','A'),
(18,'What does social stratification describe?','Random differences in daily weather','Structured inequalities between social groups','An equal distribution of all social resources','B'),
(19,'Which example illustrates horizontal occupational gender segregation?','Every occupation having equal gender representation','All employees receiving identical training','Women and men being concentrated in different types of occupations','C'),
(20,'Which example illustrates vertical occupational segregation?','Different groups being evenly spread across seniority levels','One group being concentrated in lower organisational ranks','Workers changing transport routes to work','B'),
(21,'What is intergenerational social mobility?','A change in social position between parents and their children','Moving between offices on the same floor','Changing shifts without a change in social position','A'),
(22,'Which statement about informal employment is most accurate?','It is always unpaid household activity','It can involve limited access to employment protections','It necessarily involves criminal production','B'),
(23,'Which person is unemployed under the standard labour-force concept?','A person without employment who is available and actively seeking work','A full-time worker seeking a better-paid post','A person not seeking work and unavailable to work','A'),
(24,'What is a major sociological function of trade unions?','Guaranteeing that workplace conflict can never occur','Replacing every function of management','Representing workers’ collective interests','C'),
(25,'What is a strike?','A management decision to advertise vacancies','A collective withdrawal of labour by workers','An individual request for annual leave','B'),
(26,'Which view treats workplace conflict as a normal result of differing group interests?','Unitarist perspective','The claim that organisations have no interests','Pluralist perspective','C'),
(27,'Which assumption is associated with the unitarist perspective?','The organisation is viewed as a team with shared goals','Management and labour must always have irreconcilable interests','Workplace authority can never be legitimate','A'),
(28,'Which statement about automation is most accurate?','It always eliminates every occupation immediately','It has no possible effect on skill requirements','It can replace some tasks while creating or changing others','C'),
(29,'Which feature commonly contributes to precarious platform work?','Guaranteed lifetime employment for every worker','Uncertain income and limited employment protection','Automatic collective ownership of the platform','B'),
(30,'What does work-life balance concern?','Managing the relationship between work and non-work responsibilities','Ensuring paid work occupies every waking hour','Removing all household responsibilities through job titles','A')
insert into public.questions(course_id,position,question,option_a,option_b,option_c,correct_option) select c.id,v.p,v.q,v.a,v.b,v.c,v.k from public.courses c,(values
(1,'Which statement best describes logistics?','Managing only employee recruitment','Controlling movement, storage and related information','Advertising goods to consumers','B'),
(2,'How does supply chain management relate to logistics?','It coordinates wider activities and relationships that include logistics','It excludes supplier relationships','It concerns transportation only','A'),
(3,'Which organisation is normally upstream of a furniture manufacturer?','A household buying a table','A retailer selling finished tables','A supplier of timber','C'),
(4,'Which is an example of a downstream movement?','Raw timber moving from a forest to a sawmill','Finished goods moving to a retailer','A purchase order sent to a raw-material supplier','B'),
(5,'Which item is an information flow in a supply chain?','A customer demand forecast sent to a supplier','A shipment of cartons','A cash payment to a carrier','A'),
(6,'Why is the total logistics cost approach useful?','It always chooses the cheapest transport rate','It ignores customer service','It considers combined costs rather than one cost in isolation','C'),
(7,'What is procurement primarily concerned with?','Setting consumers’ household budgets','Obtaining goods and services needed by an organisation','Preparing only promotional posters','B'),
(8,'Which document commonly communicates an internal request to buy goods?','A purchase requisition','A customer receipt','A bank statement','A'),
(9,'Which supplier selection approach is most appropriate?','Selecting the lowest quoted price regardless of quality','Choosing only suppliers owned by friends','Assessing quality, reliability and total cost','C'),
(10,'Which action is an ethical procurement practice?','Accepting a secret payment to favour a bidder','Disclosing a conflict of interest','Sharing confidential bids with a preferred supplier','B'),
(11,'Unfinished products currently being processed are which inventory category?','Work-in-progress','Finished goods','Office furniture','A'),
(12,'Which is an inventory holding cost?','The selling price charged to a customer','A customer’s transport fare','Storage and insurance expense','C'),
(13,'What is a stockout?','A planned warehouse inspection','An inability to meet demand from available stock','A delivery received ahead of schedule','B'),
(14,'What does replenishment lead time measure?','The time from placing an order to receiving it','The number of units sold each day','The amount paid for warehouse rent','A'),
(15,'Why is safety stock held?','To eliminate the need for forecasting','To guarantee zero inventory costs','To protect against demand or supply uncertainty','C'),
(16,'Daily demand is 20 units, lead time is 5 days and safety stock is 30 units. What is the reorder point?','100 units','130 units','150 units','B'),
(17,'Demand over three periods is 90, 120 and 150 units. What is the three-period moving average?','120 units','150 units','360 units','A'),
(18,'What is the bullwhip effect?','A steady decrease in transport fuel costs','The movement of expired goods to disposal','Amplification of demand variability upstream in a supply chain','C'),
(19,'Which warehouse activity checks incoming goods against delivery documents?','Order picking','Receiving','Dispatch scheduling','B'),
(20,'What does order picking involve?','Selecting stored items to fulfil an order','Negotiating a supplier contract','Forecasting next year’s inflation','A'),
(21,'What does FIFO mean in physical stock rotation?','Fastest items first out','First invoice first opened','First in, first out','C'),
(22,'Which rotation rule is especially suitable for medicines with different expiry dates?','Alphabetical order','First expiry, first out','Highest purchase price first','B'),
(23,'What is cycle counting?','Regularly counting selected inventory items','Counting all customers at the end of a year','Replacing every stock record with an estimate','A'),
(24,'Which mode is generally most suitable for small, high-value goods requiring very urgent overseas delivery?','Inland waterway transport','Ocean shipping','Air transport','C'),
(25,'Which advantage commonly favours road transport for local deliveries?','It is unaffected by traffic congestion','Flexible door-to-door service','It always has the lowest cost per tonne','B'),
(26,'A company hires an external firm to manage storage and deliveries. What is this arrangement?','Third-party logistics','Backward product design','Internal recruitment','A'),
(27,'What does last-mile delivery describe?','The first movement of raw materials to a factory','Only international sea transport','The final delivery stage to the recipient','C'),
(28,'A firm delivers 180 of 200 orders on time. What is its on-time delivery rate?','80%','90%','95%','B'),
(29,'Annual cost of goods sold is ₦1,200,000 and average inventory at cost is ₦300,000. What is inventory turnover?','4 times per year','0.25 times per year','40 times per year','A'),
(30,'Which activity is an example of reverse logistics?','Sending newly manufactured goods to a retailer','Ordering raw materials for normal production','Collecting used packaging for recycling','C')
